    try:
        return e.extents
    except Exception:
        return None

for layer in ["WALL", "DOOR", "CLEARANCE"]:
    print("="*20, layer, "="*20)
    for e in msp.query(f'*[layer=="{layer}"]'):
        t = e.dxftype()
        info = []
        if t == "LINE":
            info = [f"start=({e.dxf.start.x:.3f},{e.dxf.start.y:.3f})", f"end=({e.dxf.end.x:.3f},{e.dxf.end.y:.3f})"]
        elif t == "CIRCLE":
            info = [f"c=({e.dxf.center.x:.3f},{e.dxf.center.y:.3f}) r={e.dxf.radius:.3f}"]
        elif t == "ARC":
            info = [f"c=({e.dxf.center.x:.3f},{e.dxf.center.y:.3f}) r={e.dxf.radius:.3f}",
